package com.anssa8bu.ssafy.event.application; import com.anssa8bu.ssafy.event.publisher.EventDispatcher; import com.anssa8bu.ssafy.event.repository.OutboxEventRepository; import io.micrometer.core.instrument.*; import org.slf4j.*; import org.springframework.stereotype.Service; @Service public class OutboxPublishService {private static final Logger log=LoggerFactory.getLogger(OutboxPublishService.class);private final OutboxClaimService claim;private final OutboxResultService result;private final OutboxEventRepository repo;private final EventDispatcher dispatcher;private final Counter published,failed;public OutboxPublishService(OutboxClaimService c,OutboxResultService r,OutboxEventRepository repo,EventDispatcher d,MeterRegistry meter){claim=c;result=r;this.repo=repo;dispatcher=d;published=meter.counter("outbox.publish","result","success");failed=meter.counter("outbox.publish","result","failure");}public int publishBatch(){var ids=claim.claim();for(var id:ids){var event=repo.findById(id).orElseThrow();try{dispatcher.dispatch(event);result.published(id);published.increment();}catch(RuntimeException ex){failed.increment();log.warn("Outbox publish failed eventId={} type={} attempt={}",event.getEventId(),event.getEventType(),event.getAttempt());result.failed(id,ex.getClass().getSimpleName());}}return ids.size();}}
